  "chapter": "细胞的基本功能",
  "kp": "静息电位与动作电位",
  "style": "cn306",
  "type": "A1",
  "difficulty": 0.5,
  "stem": "在刺激作用时间无限长的情况下，引起细胞产生动作电位的最小刺激强度是( )",
