  "explain": "血液在冰库储存较久，红细胞代谢障碍，钠泵（Na+-K+-ATP酶）活性降低甚至失活，细胞内K+外漏至血浆，故血浆K+浓度升高，选C。Na+、Cl-主要分布于细胞外液，储存期间变化不大；Ca2+受抗凝剂影响，不会明显升高，故A、B、D错。",
