  "subject": "physiology",
  "chapter": "血液循环",
  "kp": "心血管活动的调节",
  "style": "cn306",
  "type": "A1",
  "difficulty": 0.5,
  "stem": "下列心交感神经对心脏的作用中，描述错误的是：",
