  "kp": "动脉血压与影响因素",
  "style": "cn306",
  "type": "A1",
  "difficulty": 0.5,
  "stem": "关于动脉血压的叙述，下列哪一项是正确的？",
  "options": [
   "心室收缩时，血液对动脉管壁的侧压称为收缩压",
   "动脉血压偏离正常水平愈远，压力感受器纠正异常血压的能力愈强",
   "其它因素不变时，心率加快使脉搏压增大",
   "男、女性的动脉血压均随年令的增长而变化"
  ],
  "answer": [
   3
  ],
  "explain": "无论男女，动脉血压均随年龄增长而升高，收缩压尤为明显，故D正确。收缩压是心室收缩期动脉血压的最高值，而非血液对管壁的侧压；血压偏离正常越远，压力感受器的纠正能力越弱；心率加快使舒张期缩短、舒张压升高、脉压减小，故A、B、C错。",
