  "explain": "快反应细胞与慢反应细胞的主要区别在于0期去极化的速度和幅度：前者由快Na+通道介导，速度快、幅度大；后者由ICa-L介导，速度慢、幅度小，故选A。4期缓慢去极速度、平台期持续时间和静息电位水平均非分类依据，故B、C、D错。",
