  "subject": "physiology",
  "chapter": "呼吸",
  "kp": "气体运输与氧解离曲线",
  "style": "cn306",
  "type": "A1",
  "difficulty": 0.5,
  "stem": "当血氧含量等于血氧容量，则血氧饱和度为",
